# Build the 30x30 mosaic from the observed tile pattern, then add matching-color links.
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for ti,r0 in enumerate(starts):
  for tj,c0 in enumerate(starts):
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r<n and c<n:
          if dr in (0,4) or dc in (0,4): g[r][c]=4
          elif ti<4 and tj<4: g[r][c]=colors[ti][tj]
# Horizontal corridors: for each complete tile row and each marker color,
# fill all inter-tile gaps between the extreme occurrences.
centers=[3,10,17,24]
for ti,r0 in enumerate(starts[:4]):
  vals=colors[ti]
  for color in set(vals):
    cols=[j for j,v in enumerate(vals) if v==color]
    for j in range(min(cols),max(cols)):
      for c in range(starts[j]+5, starts[j+1]): g[centers[ti]][c]=color
# Vertical corridors similarly, along each complete tile column.
for tj in range(4):
  vals=[colors[i][tj] for i in range(4)]
  for color in set(vals):
    rows=[i for i,v in enumerate(vals) if v==color]
    for i in range(min(rows),max(rows)):
      for r in range(starts[i]+5, starts[i+1]): g[r][centers[tj]]=color
